import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-07-28","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-07-28","date":"2021-07-28T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","代码审查","错误修复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-07-28.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-07-28.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-07-28.md"};function o(n,e,s,p,h,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph项目会议重点讨论了代码审查、性能优化、错误修复和未来工作计划。与会开发人员分享了各自的工作进展和遇到的问题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>代码审查与清理</strong></p><ul><li>开发者完成了对Bronze PR的审查，并进行了代码清理。</li><li>实现了使用可中断未来（interruptable future）的树结构，即将提交PR。</li></ul></li><li><p><strong>性能与错误分析</strong></p><ul><li>讨论了容器化环境中配置Messenger时遇到的问题，原因是使用了错误的nonce。</li><li>决定不引入nonce冲突检查机制，而是使用随机nonce来降低冲突概率。</li></ul></li><li><p><strong>性能比较工具</strong></p><ul><li>开发了比较Ceph不同存储实现（如Ceph和Crimson）性能的工具，特别是在内存对象处理方面的开销。</li><li>发现alienstore在处理4K随机读取时的性能较低。</li></ul></li><li><p><strong>日志处理与代码优化</strong></p><ul><li>讨论了日志处理改进，尤其是在PG状态日志处理方面。</li><li>开发者正在重写LBA树，并优化扩展放置管理器的PR。</li></ul></li><li><p><strong>性能测试与分析</strong></p><ul><li>进行了性能测试，包括缓存使用、事务验证和写放大效应的分析。</li><li>讨论了自动化生成性能图表的方法。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>不引入nonce冲突检查机制，使用随机nonce降低冲突风险。</li><li>继续优化alienstore性能，特别是在减少内核切换次数方面。</li><li>考虑将性能分析脚本集成到CBT工具目录中。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>提交使用可中断未来（interruptable future）的树结构的PR。</li><li>优化扩展放置管理器的PR，并解决单元测试中的问题。</li><li>完成日志处理的改进，并提交相关PR。</li><li>继续进行性能测试和分析，特别是关于写放大效应的优化。</li><li>探索自动化生成性能图表的方法，并考虑将其集成到CBT工具目录中。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到的术语如“nonce”、“interruptable future”、“alienstore”是Ceph存储系统中的关键技术概念。</li><li>会议强调了代码质量和性能优化的重要性，以及持续改进和测试的必要性。</li></ul><p>本次会议为Ceph项目的持续发展和优化提供了明确的方向和行动计划。</p>',12)])])}const c=l(r,[["render",o]]);export{_ as __pageData,c as default};
